package codegen

import (
	"bytes"
	"errors"
	"io"
	"os"
)

// generatedHeader opens every Go file the generator writes (builder.header).
// It is what marks a file as the generator's to delete.
const generatedHeader = generatedMarker + "\n"

const generatedMarker = "// Code generated by gqlc. DO NOT EDIT."

const byteOrderMark = "\ufeff"

// header renders a generated file's preamble. doc, when not empty, becomes
// the package comment: exactly one file per generated package carries one, so
// a consumer running a linter over code it cannot edit is not told to add a
// comment there, and go doc has something to show for the package.
func (b *builder) header(pkg, doc string) string {
	h := generatedHeader + "\n"
	if doc != "" {
		h += "// Package " + pkg + " " + doc + "\n"
	}
	return h + "package " + pkg + "\n\n"
}

// hasGeneratedHeader reports whether path opens with generatedMarker on a
// line of its own, reading only that much of it.
func hasGeneratedHeader(path string) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer func() { _ = f.Close() }() // read-only: a close error loses nothing
	// Room for a byte-order mark before it, which isGeneratedSource allows.
	buf := make([]byte, len(byteOrderMark)+len(generatedMarker)+1)
	n, err := io.ReadFull(f, buf)
	if err != nil && !errors.Is(err, io.ErrUnexpectedEOF) && !errors.Is(err, io.EOF) {
		return false, err
	}
	return isGeneratedSource(buf[:n]), nil
}

// isGeneratedSource reports whether src opens with generatedMarker on a line
// of its own. The line may end in \r\n: gqlc writes \n, but a checkout with
// core.autocrlf turns it into \r\n, and a file that stopped matching there
// would silently never be pruned.
func isGeneratedSource(src []byte) bool {
	// An editor may put a byte-order mark before the header. The file is
	// still gqlc's, to rewrite or to prune; refusing it as somebody else's
	// blocked every generate after.
	src = bytes.TrimPrefix(src, []byte(byteOrderMark))
	if len(src) <= len(generatedMarker) || string(src[:len(generatedMarker)]) != generatedMarker {
		return false
	}
	end := src[len(generatedMarker)]
	return end == '\n' || end == '\r'
}
